events.command:
python3 -c "
import json, os

key = open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
from bioblend.galaxy import GalaxyInstance
gi = GalaxyInstance(url='https://usegalaxy.org', key=key)

history_id = 'bbd44e69cb8906b58a14e1c991797b2f'

history_contents = gi.histories.show_history(history_id, contents=True)
datasets = {}
for item in history_contents:
    name = item.get('name', '')
    if name.startswith('sample_') and name.endswith('.csv'):
        sample_name = name.replace('.csv', '')
        datasets[sample_name] = {'id': item['id'], 'src': 'hda'}
        print(f'Found: {sample_name} -> {item[\"id\"]}')

# Create collection
collection_desc = {
    'name': 'Count files',
    'element_identifiers': [],
    'collection_type': 'list'
}

for sample in ['sample_WL1', 'sample_WL2', 'sample_WL3', 'sample_KL1', 'sample_KL2', 'sample_KL3']:
    if sample in datasets:
        collection_desc['element_identifiers'].append({
            'name': sample,
            'src': 'hda',
            'id': datasets[sample]['id']
        })
    else:
        print(f'WARNING: {sample} not found')

result = gi.histories.create_dataset_collection(history_id, collection_desc)
print('Collection result:', json.dumps(result, indent=2)[:1000])
"

